/// The awaiting pool for a vacancy, from the store (fallback to the seed
/// when the key is absent — keeps the demo crash-free on an empty store).
pub fn awaiting(store: DemoStore, vacancy_id: String) -> List(AwaitingApplicant) {
  awaiting_for(store, vacancy_id)
}

fn awaiting_for(store: DemoStore, vacancy_id: String) -> List(AwaitingApplicant) {
  case dict.get(store.awaiting, vacancy_id) {
    Ok(rows) -> rows
    Error(_) -> []
  }
}

fn result_map_custom(result: Result(a, b), f: fn(a) -> c) -> Result(c, b) {
  case result {
    Ok(a) -> Ok(f(a))
    Error(e) -> Error(e)
  }
}
